// Task 0147 slice 3: reading one entry out of a zip (the DirectML NuGet package). Zips are generated by ziphelper.hpp.
#include "editor_modules/face_editor/zip_entry.hpp"

#include "ziphelper.hpp"

#include <gtest/gtest.h>

#include <cstdlib>

namespace
{
    using namespace face_editor;
    namespace fs = std::filesystem;

    fs::path tempZip(const char* name, const std::string& bytes)
    {
        const fs::path dir = fs::temp_directory_path() / "oe_face_zip";
        const fs::path path = dir / (std::string(name) + ".zip");
        ziphelper::writeFile(path, bytes);
        return path;
    }

    std::string str(const std::vector<char>& v)
    {
        return std::string(v.begin(), v.end());
    }

    constexpr std::uint64_t kCap = 1 << 20;

    TEST(ZipEntry, readsAStoredEntryAmongOthers)
    {
        const fs::path p = tempZip("stored",
            ziphelper::makeZip(
                { { "LICENSE.txt", "licence", false }, { "bin/x64-win/DirectML.dll", "MZ-stored", false },
                    { "bin/x86-win/DirectML.dll", "wrong one", false } }));
        std::vector<char> out;
        std::string error;
        ASSERT_TRUE(readZipEntry(p, "bin/x64-win/DirectML.dll", kCap, out, error)) << error;
        EXPECT_EQ(str(out), "MZ-stored");
    }

    TEST(ZipEntry, readsADeflatedEntryOfSeveralMegabytes)
    {
        std::string data = ziphelper::noise(300000, 3) + std::string(2000000, 'x') + ziphelper::noise(100000, 4);
        const fs::path p
            = tempZip("deflated", ziphelper::makeZip({ { "a.txt", "a", false }, { "big.bin", data, true } }));
        std::vector<char> out;
        std::string error;
        ASSERT_TRUE(readZipEntry(p, "big.bin", 8u << 20, out, error)) << error;
        EXPECT_EQ(str(out), data);
    }

    TEST(ZipEntry, aMissingEntryIsAnError)
    {
        const fs::path p = tempZip("missing", ziphelper::makeZip({ { "other.dll", "x", false } }));
        std::vector<char> out;
        std::string error;
        EXPECT_FALSE(readZipEntry(p, "bin/x64-win/DirectML.dll", kCap, out, error));
        EXPECT_NE(error.find("DirectML.dll"), std::string::npos) << error;
    }

    TEST(ZipEntry, theNameMustMatchExactlyIncludingCase)
    {
        const fs::path p = tempZip("case", ziphelper::makeZip({ { "Bin/x64-win/directml.dll", "x", false } }));
        std::vector<char> out;
        std::string error;
        EXPECT_FALSE(readZipEntry(p, "bin/x64-win/DirectML.dll", kCap, out, error));
    }

    TEST(ZipEntry, anEntryOverTheCapIsRefused)
    {
        const fs::path p = tempZip("cap", ziphelper::makeZip({ { "f", std::string(5000, 'a'), true } }));
        std::vector<char> out;
        std::string error;
        EXPECT_FALSE(readZipEntry(p, "f", 4999, out, error));
        EXPECT_TRUE(readZipEntry(p, "f", 5000, out, error)) << error;
    }

    TEST(ZipEntry, aWrongCrcIsRefused)
    {
        ziphelper::Entry e{ "f", "payload payload", true };
        e.mCrcDelta = 1;
        std::vector<char> out;
        std::string error;
        EXPECT_FALSE(readZipEntry(tempZip("crc", ziphelper::makeZip({ e })), "f", kCap, out, error));
        EXPECT_NE(error.find("CRC"), std::string::npos) << error;
        e.mDeflate = false;
        EXPECT_FALSE(readZipEntry(tempZip("crc2", ziphelper::makeZip({ e })), "f", kCap, out, error));
    }

    TEST(ZipEntry, aSizeThatDisagreesWithTheDataIsRefused)
    {
        for (std::int64_t delta : { -3, 3 })
        {
            ziphelper::Entry e{ "f", std::string(1000, 'q'), true };
            e.mSizeDelta = delta;
            std::vector<char> out;
            std::string error;
            EXPECT_FALSE(readZipEntry(tempZip("size", ziphelper::makeZip({ e })), "f", kCap, out, error)) << delta;
        }
    }

    TEST(ZipEntry, anUnsupportedMethodIsRefused)
    {
        ziphelper::Entry e{ "f", "data", false };
        e.mMethodOverride = 12; // bzip2
        std::vector<char> out;
        std::string error;
        EXPECT_FALSE(readZipEntry(tempZip("method", ziphelper::makeZip({ e })), "f", kCap, out, error));
        EXPECT_NE(error.find("method"), std::string::npos) << error;
    }

    TEST(ZipEntry, notAZipAndTruncatedFilesAreRefused)
    {
        std::vector<char> out;
        std::string error;
        EXPECT_FALSE(readZipEntry(tempZip("junk", std::string(500, 'j')), "f", kCap, out, error));
        EXPECT_FALSE(readZipEntry(tempZip("empty", ""), "f", kCap, out, error));
        EXPECT_FALSE(readZipEntry(fs::temp_directory_path() / "oe_face_zip" / "nothere.zip", "f", kCap, out, error));
        const std::string whole = ziphelper::makeZip({ { "f", ziphelper::noise(4000), true }, { "g", "tail", false } });
        // Every shorter prefix is either refused or (only when the cut keeps the whole end record) valid; none crashes.
        for (std::size_t cut = 0; cut < whole.size(); cut += 17)
        {
            const bool ok = readZipEntry(tempZip("cut", whole.substr(0, cut)), "f", kCap, out, error);
            EXPECT_FALSE(ok) << cut;
        }
    }

    TEST(ZipEntry, hostileHeaderFieldsDoNotCrashOrOverread)
    {
        const std::string whole
            = ziphelper::makeZip({ { "f", ziphelper::noise(3000, 9), true }, { "g", "tail", false } });
        std::size_t refused = 0;
        // Flip every byte of the directory and headers in turn (and a few of the data): the result is a refusal or the
        // right bytes, never a crash. (CRC-32 makes a changed data byte a refusal.)
        for (std::size_t at = 0; at < whole.size(); at += 3)
        {
            std::string copy = whole;
            copy[at] = static_cast<char>(copy[at] ^ 0xA5);
            std::vector<char> out;
            std::string error;
            if (!readZipEntry(tempZip("flip", copy), "f", kCap, out, error))
                ++refused;
        }
        EXPECT_GT(refused, 100u);
    }

    TEST(ZipEntry, aZip64MarkerIsRefusedWithAMessage)
    {
        std::string z = ziphelper::makeZip({ { "f", "data", false } });
        // The end record is the last 22 bytes: set the central directory offset to 0xFFFFFFFF.
        for (int i = 0; i < 4; ++i)
            z[z.size() - 6 + static_cast<std::size_t>(i)] = static_cast<char>(0xFF);
        std::vector<char> out;
        std::string error;
        EXPECT_FALSE(readZipEntry(tempZip("zip64", z), "f", kCap, out, error));
        EXPECT_NE(error.find("zip64"), std::string::npos) << error;
    }

    TEST(ZipEntry, aZipWithATrailingCommentIsRead)
    {
        std::string z = ziphelper::makeZip({ { "f", "hello", false } });
        // Set the comment length (last two bytes of the 22 byte record) and append the comment.
        z[z.size() - 2] = 5;
        z += "extra";
        std::vector<char> out;
        std::string error;
        ASSERT_TRUE(readZipEntry(tempZip("comment", z), "f", kCap, out, error)) << error;
        EXPECT_EQ(str(out), "hello");
    }

    // The real pinned package (about 202 MB, in the download cache the build uses): gated, read only.
    TEST(ZipEntry, theRealDirectMlPackageYieldsItsDll)
    {
        const char* path = std::getenv("OPENEDEN_DML_PACKAGE");
        if (path == nullptr)
            GTEST_SKIP() << "OPENEDEN_DML_PACKAGE (Microsoft.AI.DirectML.1.15.4.nupkg) is not set";
        std::vector<char> out;
        std::string error;
        ASSERT_TRUE(readZipEntry(path, "bin/x64-win/DirectML.dll", 64u << 20, out, error)) << error;
        EXPECT_GT(out.size(), 10u << 20);
        EXPECT_EQ(out[0], 'M');
        EXPECT_EQ(out[1], 'Z');
    }
}
